#!/usr/bin/env bash
# regen-bindings.sh -- Regenerate the committed FFI bindings for a Unix host.
#
# Generates crates/pyrfcx-core/src/ffi/bindings_<target>.rs for the host
# target (one per-target file, see ffi/mod.rs). The Windows file
# (bindings.rs) is generated by regen-bindings.ps1.
#
# The bindgen flags and the function/type allowlists are read from
# regen-bindings.ps1, so the two scripts cannot drift apart.
#
# Prerequisites: bindgen-cli (cargo install bindgen-cli), libclang
# (Xcode Command Line Tools on macOS; on Linux the image built from
# tools/docker/Dockerfile.linux, see `just linux-regen-bindings`), the SDK
# at vendor/nwrfcsdk.
# Usage: just regen-bindings  (or: bash tools/regen-bindings.sh)

set -euo pipefail

cd "$(dirname "$0")/.."

case "$(uname -s)-$(uname -m)" in
    Darwin-arm64) target="aarch64-apple-darwin" ;;
    Linux-x86_64) target="x86_64-unknown-linux-gnu" ;;
    Linux-aarch64) target="aarch64-unknown-linux-gnu" ;;
    *)
        echo "regen-bindings.sh: no per-target bindings for $(uname -s)-$(uname -m)" >&2
        exit 1
        ;;
esac

wrapper_h="crates/pyrfcx-core/src/ffi/wrapper.h"
output_file="crates/pyrfcx-core/src/ffi/bindings_${target//-/_}.rs"
include_dir="vendor/nwrfcsdk/include"

# Allowlists: every quoted name inside the $Functions / $Types arrays of the
# PowerShell script, comments stripped.
allowlist() {
    sed -n "/^\\\$$1 = @(/,/^)/p" tools/regen-bindings.ps1 \
        | sed 's/#.*//' \
        | grep -o "'[^']*'" \
        | tr -d "'"
}

args=(
    "$wrapper_h"
    --dynamic-loading SapNwRfc
    --dynamic-link-require-all
    --default-enum-style newtype
    # The header's comments are SAP's text; our license cannot cover them.
    --no-doc-comments
)
while read -r f; do args+=(--allowlist-function "$f"); done < <(allowlist Functions)
while read -r t; do args+=(--allowlist-type "$t"); done < <(allowlist Types)

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

echo "Generating bindings for $target..."
bindgen "${args[@]}" -o "$tmp" -- -DSAPwithUNICODE -DSAP_API= "-I$include_dir" "--target=$target"

bindgen_version="$(bindgen --version | sed 's/^bindgen //')"
{
    echo "// Auto-generated by bindgen $bindgen_version -- do not edit."
    echo "// Regenerate with: just regen-bindings (on an $target host)"
    echo "// SDK headers: SAP NW RFC SDK 7.50 (vendor/nwrfcsdk/include/sapnwrfc.h)"
    echo "// Defines: -DSAPwithUNICODE -DSAP_API="
    echo "// Date: $(date +%Y-%m-%d)"
    echo "// Targets verified: $target"
    echo
    cat "$tmp"
} > "$output_file"

echo "Written: $output_file"
